// Prontuario completo degli incantesimi del Manuale del Giocatore 2024 (capitolo 7): 391 incantesimi.
// Le descrizioni sono RIASSUNTI in italiano scritti per l'app, non il testo del manuale (l'app è pubblica);
// i numeri (danni, distanze, CD, durate) sono stati controllati sulle pagine del manuale.
// Distanze in metri come nel manuale italiano (1,5 m per ogni 5 piedi). Il nome inglese (en) aiuta a cercare.
// Classi: B Bardo, C Chierico, D Druido, P Paladino, R Ranger, S Stregone, W Warlock, M Mago.
const CL = { B: 'Bardo', C: 'Chierico', D: 'Druido', P: 'Paladino', R: 'Ranger', S: 'Stregone', W: 'Warlock', M: 'Mago' };
const S = (nome, en, livello, scuola, tempo, gittata, componenti, durata, classi, descrizione) => ({
  nome, en, livello, scuola, tempo, gittata, componenti, durata, descrizione,
  classi: classi.split(' ').map((k) => CL[k]).filter(Boolean),
  concentrazione: /^Concentrazione/i.test(durata), rituale: /rituale/i.test(tempo),
});
const SU = (n) => `Ai livelli superiori: ${n}.`;   // testo per gli slot di livello più alto

